"""Training memory for weights, gradients and optimiser state (activations not included).

The configuration is an 8-billion-parameter Llama-style model: change it to see any other.
"""

CONFIG = {"vocab": 128_256, "hidden": 4_096, "mlp": 14_336, "layers": 32, "heads": 32, "kv_heads": 8, "head_dim": 128}


def linear_shapes(c):
    """(d_in, d_out) of every linear layer in one transformer block."""
    q, kv = c["heads"] * c["head_dim"], c["kv_heads"] * c["head_dim"]
    return {"q_proj": (c["hidden"], q), "k_proj": (c["hidden"], kv), "v_proj": (c["hidden"], kv),
            "o_proj": (q, c["hidden"]), "gate_proj": (c["hidden"], c["mlp"]), "up_proj": (c["hidden"], c["mlp"]),
            "down_proj": (c["mlp"], c["hidden"])}


def total_params(c):
    per_block = sum(i * o for i, o in linear_shapes(c).values()) + 2 * c["hidden"]  # plus two norm weights
    return c["layers"] * per_block + 2 * c["vocab"] * c["hidden"] + c["hidden"]   # untied embeddings and head


def lora_params(c, r, targets):
    # TODO 1: each targeted layer adds r * (d_in + d_out) parameters, in every one of the c["layers"] blocks
    return 0


def full_gb(params):
    # TODO 2: mixed-precision AdamW keeps 16 bytes per parameter: bf16 weights (2) and gradients (2),
    #          an fp32 master copy (4) and two fp32 moments (4 + 4)
    return 0


def lora_gb(params, trainable, base_bytes=2.0):
    """A frozen base (2 bytes per parameter in bf16) plus 16 bytes per trainable LoRA parameter."""
    return (params * base_bytes + trainable * 16) / 1e9


def qlora_gb(params, trainable):
    """Module 4: NF4 weights are 4 bits plus about 0.127 bits of double-quantised constants per parameter."""
    return lora_gb(params, trainable, base_bytes=(4 + 0.127) / 8)


def main():
    n = total_params(CONFIG)
    everything = list(linear_shapes(CONFIG))
    print(f"Model parameters: {n:,}")
    for r, targets in ((16, ["q_proj", "v_proj"]), (16, everything), (64, everything)):
        t = lora_params(CONFIG, r, targets)
        label = "all linear layers" if targets == everything else " and ".join(targets)
        print(f"LoRA r={r} on {label}: {t:,} trainable ({t / n:.2%})")
    t = lora_params(CONFIG, 16, everything)
    print(f"Full fine-tuning:  {full_gb(n):6.1f} GB")
    print(f"LoRA, bf16 base:   {lora_gb(n, t):6.1f} GB")
    print(f"QLoRA, 4-bit base: {qlora_gb(n, t):6.1f} GB")


if __name__ == "__main__":
    main()

"""LoRA from scratch: a frozen nn.Linear plus a trainable low-rank update, scaled by alpha / r."""

import math

import torch
import torch.nn as nn

TARGETS = ("q_proj", "k_proj", "v_proj", "o_proj", "up_proj", "down_proj")


class LoRALinear(nn.Module):
    def __init__(self, base: nn.Linear, r: int, alpha: float, dropout: float = 0.0):
        super().__init__()
        self.base = base
        for p in self.base.parameters():
            p.requires_grad_(False)
        # TODO 1: create self.A, an nn.Parameter of shape (r, in_features) initialised with
        #          nn.init.kaiming_uniform_(..., a=math.sqrt(5)) as nn.Linear does; self.B, an nn.Parameter of
        #          zeros of shape (out_features, r); and self.scale = alpha / r
        self.A = self.B = None
        self.scale = 1.0
        self.dropout = nn.Dropout(dropout)

    def forward(self, x):
        # TODO 2: the base layer's output plus scale * (dropout(x) @ A^T @ B^T)
        return self.base(x)

    @torch.no_grad()
    def merged(self) -> nn.Linear:
        """A plain nn.Linear whose weight is W + scale * B @ A: the same outputs, at no extra cost."""
        out = nn.Linear(self.base.in_features, self.base.out_features, bias=self.base.bias is not None)
        # TODO 3: copy the merged weight into out.weight, and the base bias (if any) into out.bias
        pass
        return out


def add_lora(model, r, alpha, targets=TARGETS):
    """Freeze the model, wrap every targeted nn.Linear in a LoRALinear, and return the new trainable parameters."""
    for p in model.parameters():
        p.requires_grad_(False)
    params = []
    for module in list(model.modules()):
        for name, child in list(module.named_children()):
            if name in targets and isinstance(child, nn.Linear):
                wrapped = LoRALinear(child, r, alpha)
                setattr(module, name, wrapped)
                params += [wrapped.A, wrapped.B]
    return params


def merge_lora(model):
    """Replace every LoRALinear with its merged nn.Linear."""
    for module in list(model.modules()):
        for name, child in list(module.named_children()):
            if isinstance(child, LoRALinear):
                setattr(module, name, child.merged())
    return model

